import{_ as s,I as r,o as g,c as h,b6 as o,J as e}from"./chunks/framework.COUcLbTA.js";const C=JSON.parse('{"title":"AI Agent 协议（MCP & A2A）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/8-artificial-intelligence/ai-protocols.md","filePath":"zh-cn/appendix/8-artificial-intelligence/ai-protocols.md"}'),A={name:"zh-cn/appendix/8-artificial-intelligence/ai-protocols.md"};function c(p,t,b,_,u,P){const a=r("McpVisualDemo"),n=r("McpDetailedDemo"),d=r("A2AVisualDemo"),l=r("A2ADetailedDemo"),i=r("ProtocolComparisonDemo");return g(),h("div",null,[t[0]||(t[0]=o('<h1 id="ai-agent-协议-mcp-a2a" tabindex="-1">AI Agent 协议（MCP &amp; A2A） <a class="header-anchor" href="#ai-agent-协议-mcp-a2a" aria-label="Permalink to “AI Agent 协议（MCP &amp; A2A）”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">核心问题</p><p><strong>AI Agent 如何与外部世界&quot;对话&quot;？</strong> 就像互联网需要 HTTP 协议，AI Agent 也需要标准化的通信协议。本章介绍两个最主流的 Agent 协议：MCP 和 A2A，它们分别解决了 AI 与工具、Agent 与 Agent 之间的通信问题。</p></div><hr><h2 id="_0-什么是协议" tabindex="-1">0. 什么是协议？ <a class="header-anchor" href="#_0-什么是协议" aria-label="Permalink to “0. 什么是协议？”">​</a></h2><p>在计算机领域，<strong>协议（Protocol）</strong> 是一套标准化的规则和约定，让不同的系统、程序能够相互&quot;理解&quot;和&quot;通信&quot;。</p><h3 id="_0-1-为什么需要协议" tabindex="-1">0.1 为什么需要协议？ <a class="header-anchor" href="#_0-1-为什么需要协议" aria-label="Permalink to “0.1 为什么需要协议？”">​</a></h3><p>想象一个场景：你给朋友寄快递，需要填写地址。如果每个人写的地址格式都不一样，快递员就没法投递。协议就是规定了&quot;地址怎么写&quot;的标准——省、市、区、街道、门牌号，按这个格式写，谁都能看懂。</p><p>计算机也是一样。两个程序要通信，必须约定好：</p><ul><li>数据格式是什么？（JSON？二进制？）</li><li>怎么建立连接？（握手流程）</li><li>出错了怎么办？（错误处理）</li></ul><h3 id="_0-2-计算机中常见的协议" tabindex="-1">0.2 计算机中常见的协议 <a class="header-anchor" href="#_0-2-计算机中常见的协议" aria-label="Permalink to “0.2 计算机中常见的协议”">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>作用</th><th>你每天都在用</th></tr></thead><tbody><tr><td><strong>HTTP</strong></td><td>网页传输协议</td><td>浏览器打开网页</td></tr><tr><td><strong>HTTPS</strong></td><td>加密的 HTTP</td><td>网银、支付页面</td></tr><tr><td><strong>TCP/IP</strong></td><td>互联网基础协议</td><td>所有网络通信</td></tr><tr><td><strong>DNS</strong></td><td>域名解析协议</td><td>把 <code>google.com</code> 变成 IP 地址</td></tr><tr><td><strong>SMTP</strong></td><td>邮件发送协议</td><td>发送邮件</td></tr><tr><td><strong>WebSocket</strong></td><td>双向实时通信</td><td>聊天软件、在线游戏</td></tr><tr><td><strong>SSH</strong></td><td>安全远程登录</td><td>连接服务器</td></tr><tr><td><strong>FTP</strong></td><td>文件传输协议</td><td>上传/下载文件</td></tr></tbody></table><p>这些协议构成了互联网的基石。没有它们，你无法浏览网页、发送邮件、观看视频。</p><h3 id="_0-3-协议的价值" tabindex="-1">0.3 协议的价值 <a class="header-anchor" href="#_0-3-协议的价值" aria-label="Permalink to “0.3 协议的价值”">​</a></h3><p>协议的核心价值是<strong>标准化</strong>和<strong>互操作性</strong>：</p><ul><li><strong>标准化</strong>：大家都按同一套规则办事，减少沟通成本</li><li><strong>互操作性</strong>：不同厂商、不同技术栈的系统可以无缝对接</li></ul><p>比如 HTTP 协议，让 Chrome 浏览器可以访问 Nginx 服务器，让 Python 爬虫可以抓取 Java 网站的数据。不需要 Chrome 和 Nginx 互相&quot;认识&quot;，只要都遵守 HTTP 协议就行。</p><h3 id="_0-4-ai-agent-也需要协议" tabindex="-1">0.4 AI Agent 也需要协议 <a class="header-anchor" href="#_0-4-ai-agent-也需要协议" aria-label="Permalink to “0.4 AI Agent 也需要协议”">​</a></h3><p>AI Agent 要真正&quot;干活&quot;，需要：</p><ul><li>调用外部工具（查天气、发邮件、操作数据库）</li><li>与其他 Agent 协作（分工合作完成复杂任务）</li></ul><p>这就需要标准化的协议来规定&quot;AI 怎么调用工具&quot;、&quot;Agent 之间怎么对话&quot;。这就是 <strong>MCP</strong> 和 <strong>A2A</strong> 的由来。</p><hr><h2 id="_1-agent-协议的层次" tabindex="-1">1. Agent 协议的层次 <a class="header-anchor" href="#_1-agent-协议的层次" aria-label="Permalink to “1. Agent 协议的层次”">​</a></h2><p>在深入了解具体协议之前，让我们先看看 Agent 生态中的通信层次：</p><table tabindex="0"><thead><tr><th>层级</th><th>协议</th><th>解决的问题</th><th>类比</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>Function Call</td><td>AI 如何调用本地函数</td><td>大脑发出指令</td></tr><tr><td><strong>2</strong></td><td><strong>MCP</strong></td><td>AI 如何连接外部工具和数据源</td><td>USB-C 接口</td></tr><tr><td><strong>3</strong></td><td><strong>A2A</strong></td><td>Agent 之间如何协作通信</td><td>企业微信</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">逐行解读这张表</p><p><strong>第1层（Function Call）</strong>：这是大模型最基础的能力——通过输出结构化数据（JSON）来触发函数执行。它是&quot;协议&quot;的基础，但本身更像是一种能力而非标准协议。</p><p><strong>第2层（MCP）</strong>：Model Context Protocol，由 Anthropic 于 2024 年 11 月发布。它标准化了 AI 与外部工具、数据源的连接方式，就像 USB-C 统一了各种设备的充电接口。</p><p><strong>第3层（A2A）</strong>：Agent-to-Agent Protocol，由 Google 于 2025 年 4 月发布。它让不同的 Agent 能够相互发现、通信和协作，就像企业微信让同事之间可以发任务、聊天。</p></div><p>本章重点介绍第 2、3 层的两个正式协议：MCP 和 A2A。</p><hr><h2 id="_2-mcp-model-context-protocol" tabindex="-1">2. MCP (Model Context Protocol) <a class="header-anchor" href="#_2-mcp-model-context-protocol" aria-label="Permalink to “2. MCP (Model Context Protocol)”">​</a></h2><h3 id="_2-1-协议基本信息" tabindex="-1">2.1 协议基本信息 <a class="header-anchor" href="#_2-1-协议基本信息" aria-label="Permalink to “2.1 协议基本信息”">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>全称</strong></td><td>Model Context Protocol</td></tr><tr><td><strong>发起方</strong></td><td>Anthropic</td></tr><tr><td><strong>发布时间</strong></td><td>2024 年 11 月 25 日</td></tr><tr><td><strong>官方文档</strong></td><td><a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">modelcontextprotocol.io</a></td></tr><tr><td><strong>开源协议</strong></td><td>MIT License</td></tr><tr><td><strong>GitHub</strong></td><td><a href="https://github.com/modelcontextprotocol" target="_blank" rel="noreferrer">github.com/modelcontextprotocol</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么叫&quot;Context Protocol&quot;？</p><p><strong>Context（上下文）</strong> 是大模型理解任务的关键。MCP 的核心思想是：<strong>让 AI 能够动态获取所需的上下文信息</strong>，而不是把所有信息都塞进 Prompt。</p><p>比如，AI 需要读取一个文件时，不需要你把文件内容复制粘贴给它，而是通过 MCP 直接访问文件系统。</p></div><h3 id="_2-2-发布的背景" tabindex="-1">2.2 发布的背景 <a class="header-anchor" href="#_2-2-发布的背景" aria-label="Permalink to “2.2 发布的背景”">​</a></h3><p>2024 年，随着 Claude 3.5 Sonnet 的发布，Anthropic 发现一个问题：<strong>每个工具都要单独集成</strong>。</p><p>想象一下：</p><ul><li>你想让 AI 读取 GitHub 仓库 → 要写 GitHub 集成代码</li><li>你想让 AI 查询数据库 → 要写数据库集成代码</li><li>你想让 AI 操作文件系统 → 要写文件系统集成代码</li></ul><p>每个集成都要重复写类似的代码：认证、错误处理、数据转换……</p><p>Anthropic 在官方博客中写道：</p><blockquote><p>&quot;We&#39;re introducing the Model Context Protocol (MCP), an open protocol that standardizes how applications provide context to LLMs.&quot;</p></blockquote><p><strong>核心目标</strong>：让工具开发者写一次代码，所有支持 MCP 的 AI 应用都能使用。</p><h3 id="_2-3-mcp-是什么" tabindex="-1">2.3 MCP 是什么？ <a class="header-anchor" href="#_2-3-mcp-是什么" aria-label="Permalink to “2.3 MCP 是什么？”">​</a></h3>',40)),e(a),t[1]||(t[1]=o('<p><strong>三大核心能力</strong>：</p><table tabindex="0"><thead><tr><th>能力</th><th>英文</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><strong>工具</strong></td><td>Tools</td><td>AI 可以调用的功能</td><td>查询天气、发送邮件</td></tr><tr><td><strong>资源</strong></td><td>Resources</td><td>AI 可以读取的数据</td><td>文件内容、数据库记录</td></tr><tr><td><strong>提示</strong></td><td>Prompts</td><td>预定义的提示模板</td><td>代码审查模板、写作模板</td></tr></tbody></table><h3 id="_2-4-mcp-的内部实现" tabindex="-1">2.4 MCP 的内部实现 <a class="header-anchor" href="#_2-4-mcp-的内部实现" aria-label="Permalink to “2.4 MCP 的内部实现”">​</a></h3>',3)),e(n),t[2]||(t[2]=o('<h3 id="_2-5-类比理解-usb-c-接口" tabindex="-1">2.5 类比理解：USB-C 接口 <a class="header-anchor" href="#_2-5-类比理解-usb-c-接口" aria-label="Permalink to “2.5 类比理解：USB-C 接口”">​</a></h3><p>MCP 就像 <strong>USB-C 接口</strong>：</p><ul><li><strong>以前</strong>：每个设备都有自己的充电口（圆口、扁口、磁吸……）</li><li><strong>现在</strong>：USB-C 统一了所有设备的充电和数据传输</li><li><strong>MCP</strong>：统一了 AI 与所有工具的连接方式</li></ul><p>工具开发者只需要实现一次 MCP Server，所有支持 MCP 的 AI 应用（Claude、Cursor、Windsurf 等）都能直接使用。</p><h3 id="_2-6-mcp-的典型应用场景" tabindex="-1">2.6 MCP 的典型应用场景 <a class="header-anchor" href="#_2-6-mcp-的典型应用场景" aria-label="Permalink to “2.6 MCP 的典型应用场景”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>本地文件操作</strong></td><td>让 AI 读取/修改本地文件</td><td>读取代码库、分析日志文件</td></tr><tr><td><strong>数据库查询</strong></td><td>让 AI 直接查询数据库</td><td>SQL 查询、数据分析</td></tr><tr><td><strong>API 调用</strong></td><td>让 AI 调用第三方服务</td><td>GitHub API、Slack、邮件</td></tr><tr><td><strong>开发工具集成</strong></td><td>让 AI 使用开发工具</td><td>Git 操作、终端命令</td></tr></tbody></table><p><strong>实际案例</strong>：</p><ul><li><strong>Cursor/Windsurf</strong>：通过 MCP 连接文件系统、Git、终端</li><li><strong>Claude Desktop</strong>：通过 MCP 连接笔记软件、邮件客户端</li><li><strong>自动化脚本</strong>：让 AI 执行自动化任务（备份、部署、数据同步）</li></ul><hr><h2 id="_3-a2a-agent-to-agent-protocol" tabindex="-1">3. A2A (Agent-to-Agent Protocol) <a class="header-anchor" href="#_3-a2a-agent-to-agent-protocol" aria-label="Permalink to “3. A2A (Agent-to-Agent Protocol)”">​</a></h2><h3 id="_3-1-协议基本信息" tabindex="-1">3.1 协议基本信息 <a class="header-anchor" href="#_3-1-协议基本信息" aria-label="Permalink to “3.1 协议基本信息”">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>全称</strong></td><td>Agent-to-Agent Protocol</td></tr><tr><td><strong>发起方</strong></td><td>Google</td></tr><tr><td><strong>发布时间</strong></td><td>2025 年 4 月 9 日</td></tr><tr><td><strong>官方文档</strong></td><td><a href="https://google.github.io/A2A" target="_blank" rel="noreferrer">google.github.io/A2A</a></td></tr><tr><td><strong>开源协议</strong></td><td>Apache 2.0</td></tr><tr><td><strong>GitHub</strong></td><td><a href="https://github.com/google/A2A" target="_blank" rel="noreferrer">github.com/google/A2A</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么是 Google 发起？</p><p>Google 在 Cloud Next 2025 大会上发布 A2A，与其企业级 AI 战略密切相关。</p><p>Google 认为：未来的企业 AI 不是单个超级 Agent，而是<strong>多个专业 Agent 协作</strong>——有的负责数据分析，有的负责代码生成，有的负责文档处理。</p><p>这些 Agent 需要一种标准化的方式相互通信，A2A 应运而生。</p></div><h3 id="_3-2-发布的背景" tabindex="-1">3.2 发布的背景 <a class="header-anchor" href="#_3-2-发布的背景" aria-label="Permalink to “3.2 发布的背景”">​</a></h3><p>MCP 解决了&quot;AI 如何连接工具&quot;的问题，但还有一个问题：<strong>多个 Agent 如何协作？</strong></p><p>想象一个场景：</p><ul><li>Agent A 是&quot;需求分析专家&quot;</li><li>Agent B 是&quot;代码生成专家&quot;</li><li>Agent C 是&quot;测试专家&quot;</li></ul><p>用户说：&quot;帮我开发一个登录功能&quot;</p><p>Agent A 分析需求后，需要把任务分配给 Agent B；Agent B 写完代码后，需要让 Agent C 测试。它们之间如何通信？</p><p>Google 在官方博客中写道：</p><blockquote><p>&quot;A2A is an open protocol that enables AI agents to communicate with each other, facilitating collaboration across different frameworks and vendors.&quot;</p></blockquote><p><strong>核心目标</strong>：让不同厂商、不同框架开发的 Agent 能够无缝协作。</p><h3 id="_3-3-a2a-是什么" tabindex="-1">3.3 A2A 是什么？ <a class="header-anchor" href="#_3-3-a2a-是什么" aria-label="Permalink to “3.3 A2A 是什么？”">​</a></h3>',23)),e(d),t[3]||(t[3]=o('<p><strong>三大核心概念</strong>：</p><table tabindex="0"><thead><tr><th>概念</th><th>英文</th><th>作用</th><th>类比</th></tr></thead><tbody><tr><td><strong>Agent Card</strong></td><td>Agent 名片</td><td>描述 Agent 的能力</td><td>员工工牌</td></tr><tr><td><strong>Task</strong></td><td>任务</td><td>要执行的工作单元</td><td>工单</td></tr><tr><td><strong>Message</strong></td><td>消息</td><td>Agent 之间的通信内容</td><td>聊天记录</td></tr></tbody></table><h3 id="_3-4-a2a-的内部实现" tabindex="-1">3.4 A2A 的内部实现 <a class="header-anchor" href="#_3-4-a2a-的内部实现" aria-label="Permalink to “3.4 A2A 的内部实现”">​</a></h3>',3)),e(l),t[4]||(t[4]=o('<h3 id="_3-5-类比理解-企业微信" tabindex="-1">3.5 类比理解：企业微信 <a class="header-anchor" href="#_3-5-类比理解-企业微信" aria-label="Permalink to “3.5 类比理解：企业微信”">​</a></h3><p>A2A 就像 <strong>企业微信</strong>：</p><ul><li><strong>Agent Card</strong>：每个人的名片，显示姓名、部门、职责</li><li><strong>发任务</strong>：@某人，分配一个任务</li><li><strong>聊天沟通</strong>：任务执行过程中可以随时沟通</li><li><strong>任务追踪</strong>：能看到任务的进度和状态</li></ul><p>不同的 Agent 就像不同的同事，A2A 让它们能够协作完成复杂项目。</p><h3 id="_3-6-a2a-的典型应用场景" tabindex="-1">3.6 A2A 的典型应用场景 <a class="header-anchor" href="#_3-6-a2a-的典型应用场景" aria-label="Permalink to “3.6 A2A 的典型应用场景”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>软件开发</strong></td><td>多 Agent 协作完成开发任务</td><td>需求分析→代码→测试→部署</td></tr><tr><td><strong>企业工作流</strong></td><td>不同部门 Agent 协作处理业务</td><td>HR Agent + 财务 Agent + 法务 Agent</td></tr><tr><td><strong>智能客服</strong></td><td>多个专业 Agent 分工处理</td><td>接待→解答→转接→记录</td></tr><tr><td><strong>数据分析</strong></td><td>多个 Agent 协作分析数据</td><td>收集→清洗→分析→可视化→报告</td></tr></tbody></table><p><strong>实际案例</strong>：</p><ul><li><strong>Google Agent Space</strong>：企业内部多个 Agent 协作处理文档、邮件、日程</li><li><strong>软件开发团队</strong>：需求 Agent → 代码 Agent → 测试 Agent → 部署 Agent</li><li><strong>智能客服系统</strong>：接待 Agent → 专业解答 Agent → 人工转接 Agent</li></ul><hr><h2 id="_4-mcp-vs-a2a-对比与关系" tabindex="-1">4. MCP vs A2A：对比与关系 <a class="header-anchor" href="#_4-mcp-vs-a2a-对比与关系" aria-label="Permalink to “4. MCP vs A2A：对比与关系”">​</a></h2><h3 id="_4-1-核心差异" tabindex="-1">4.1 核心差异 <a class="header-anchor" href="#_4-1-核心差异" aria-label="Permalink to “4.1 核心差异”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>MCP</th><th>A2A</th></tr></thead><tbody><tr><td><strong>发起方</strong></td><td>Anthropic (2024.11)</td><td>Google (2025.04)</td></tr><tr><td><strong>定位</strong></td><td>AI 与工具的连接</td><td>Agent 与 Agent 的协作</td></tr><tr><td><strong>通信范围</strong></td><td>Client-Server</td><td>Peer-to-Peer</td></tr><tr><td><strong>数据格式</strong></td><td>JSON-RPC 2.0</td><td>HTTP + JSON</td></tr><tr><td><strong>类比</strong></td><td>USB-C 接口</td><td>企业微信</td></tr></tbody></table><h3 id="_4-2-两者的关系" tabindex="-1">4.2 两者的关系 <a class="header-anchor" href="#_4-2-两者的关系" aria-label="Permalink to “4.2 两者的关系”">​</a></h3><p>MCP 和 A2A <strong>不是竞争关系，而是互补关系</strong>：</p>',14)),e(i),t[5]||(t[5]=o('<h3 id="_4-3-如何选择" tabindex="-1">4.3 如何选择？ <a class="header-anchor" href="#_4-3-如何选择" aria-label="Permalink to “4.3 如何选择？”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>让 AI 调用本地函数或工具</td><td>Function Call</td></tr><tr><td>使用第三方工具（数据库、API、文件系统）</td><td>MCP</td></tr><tr><td>构建多 Agent 协作系统</td><td>A2A</td></tr><tr><td>同时需要工具集成和多 Agent 协作</td><td>MCP + A2A</td></tr></tbody></table><hr><h2 id="_5-协议的未来趋势" tabindex="-1">5. 协议的未来趋势 <a class="header-anchor" href="#_5-协议的未来趋势" aria-label="Permalink to “5. 协议的未来趋势”">​</a></h2><h3 id="_5-1-生态发展" tabindex="-1">5.1 生态发展 <a class="header-anchor" href="#_5-1-生态发展" aria-label="Permalink to “5.1 生态发展”">​</a></h3><p><strong>MCP 生态</strong>（截至 2025 年初）：</p><ul><li>官方提供的 Server：文件系统、SQLite、Git、PostgreSQL 等</li><li>社区贡献的 Server：Slack、Notion、Figma、Stripe 等</li><li>支持 MCP 的应用：Claude Desktop、Cursor、Windsurf、Zed 等</li></ul><p><strong>A2A 生态</strong>（刚发布）：</p><ul><li>Google 自家的 Agent 产品率先支持</li><li>开源社区正在开发各种语言的 SDK</li><li>企业级应用正在探索中</li></ul><h3 id="_5-2-标准化进程" tabindex="-1">5.2 标准化进程 <a class="header-anchor" href="#_5-2-标准化进程" aria-label="Permalink to “5.2 标准化进程”">​</a></h3><p>目前 Agent 协议还处于&quot;战国时代&quot;：</p><ul><li>MCP 和 A2A 是最主流的两个</li><li>还有其他新兴协议如 ANP、AGP 等</li><li>未来可能会融合或统一</li></ul><p>类比互联网的发展：</p><ul><li>早期：各种局域网协议并存</li><li>后来：TCP/IP 成为标准</li><li>现在：Agent 协议可能也会走向统一</li></ul><hr><h2 id="_6-小结" tabindex="-1">6. 小结 <a class="header-anchor" href="#_6-小结" aria-label="Permalink to “6. 小结”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">核心要点</p><table tabindex="0"><thead><tr><th>协议</th><th>一句话理解</th><th>发布时间</th><th>发起方</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>MCP</strong></td><td>AI 连接工具的&quot;USB-C&quot;</td><td>2024.11</td><td>Anthropic</td><td>工具集成、数据源连接</td></tr><tr><td><strong>A2A</strong></td><td>Agent 协作的&quot;企业微信&quot;</td><td>2025.04</td><td>Google</td><td>多 Agent 协作、任务委托</td></tr></tbody></table><p><strong>关键洞察</strong>：</p><ol><li>MCP 解决&quot;AI 如何获取外部能力&quot;的问题</li><li>A2A 解决&quot;多个 AI 如何协作&quot;的问题</li><li>两者互补，未来可能会融合使用</li><li>选择协议要根据具体场景，没有银弹</li></ol></div><hr><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ol><li><strong>MCP 官方文档</strong>: <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">modelcontextprotocol.io</a></li><li><strong>MCP GitHub</strong>: <a href="https://github.com/modelcontextprotocol" target="_blank" rel="noreferrer">github.com/modelcontextprotocol</a></li><li><strong>Anthropic 发布博客</strong>: &quot;Introducing the Model Context Protocol&quot; (2024-11-25)</li><li><strong>A2A 官方文档</strong>: <a href="https://google.github.io/A2A" target="_blank" rel="noreferrer">google.github.io/A2A</a></li><li><strong>A2A GitHub</strong>: <a href="https://github.com/google/A2A" target="_blank" rel="noreferrer">github.com/google/A2A</a></li><li><strong>Google Cloud Blog</strong>: &quot;Announcing the Agent-to-Agent Protocol&quot; (2025-04-09)</li></ol>',20))])}const x=s(A,[["render",c]]);export{C as __pageData,x as default};
